// === CONFIGURATION ===
const SKILLS_REPOS = [
  { owner: 'YOUR_GITHUB_USERNAME', repo: 'business-memory-skills' }
];

const allSkills = [];

for (const { owner, repo } of SKILLS_REPOS) {
  const skillsUrl = `https://api.github.com/repos/${owner}/${repo}/contents/skills/`;
  const skillsResp = await this.helpers.httpRequest({
    method: 'GET',
    url: skillsUrl,
    headers: {
      'Accept': 'application/vnd.github.v3+json',
      'User-Agent': 'n8n-skills-agent'
    }
  });

  for (const item of skillsResp) {
    if (item.type === 'dir') {
      allSkills.push({
        skill: item.name,
        path: `skills/${item.name}/SKILL.md`
      });
    }
  }
}

const directoryMap = allSkills.map(s => `- **${s.skill}** : \`${s.path}\``).join('\n');

return [{ json: { directoryMap, skillsList: allSkills } }];
